// Nó Code "Ler mensagens" do workflow "Bot da Pauta" (modo: Run Once for All Items)
// Faz o long polling no Telegram (getUpdates segura a conexão por até 30 s), confirma a leitura
// e devolve um item por mensagem nova (texto ou áudio) vinda do chat autorizado (TELEGRAM_CHAT_ID).
// As chamadas ficam aqui, e não num nó HTTP, porque o token do bot vai na URL e o nó HTTP grava
// a URL inteira no log quando falha. Aqui o erro sai sem o token.

const token = $env.TELEGRAM_BOT_TOKEN;
const semToken = (e) => String(e?.message ?? e).split(token).join('***');
const getUpdates = (qs, timeout) =>
  this.helpers.httpRequest({ url: `https://api.telegram.org/bot${token}/getUpdates`, qs, json: true, timeout });

let updates;
try {
  updates = (await getUpdates({ timeout: 30, allowed_updates: '["message"]' }, 45000)).result ?? [];
} catch (e) {
  throw new Error(`Falha ao ler mensagens do Telegram: ${semToken(e)}`);
}
if (updates.length === 0) return [];

// Chamar getUpdates com offset = último id + 1 faz o Telegram esquecer as mensagens já lidas.
// Confirmar antes de responder evita resposta repetida se a próxima execução começar antes desta acabar.
// Se a confirmação falhar, nada é respondido agora: a próxima execução lê as mesmas mensagens.
try {
  await getUpdates({ offset: updates[updates.length - 1].update_id + 1, timeout: 0, limit: 1 }, 15000);
} catch (e) {
  throw new Error(`Falha ao confirmar a leitura no Telegram: ${semToken(e)}`);
}

const chatAutorizado = String($env.TELEGRAM_CHAT_ID);
const agora = Math.floor(Date.now() / 1000);

return updates
  .map((u) => u.message)
  .filter((m) => m && String(m.chat.id) === chatAutorizado)
  .filter((m) => agora - m.date < 10 * 60) // ignora mensagem com mais de 10 min (ex.: enviada com o n8n desligado)
  .map((m) => {
    const audio = m.voice ?? m.audio; // voice = gravado no microfone; audio = arquivo de áudio enviado
    return {
      chatId: m.chat.id,
      // Em grupo, o Telegram só entrega ao bot comandos e menções: tira o "@nome_do_bot" e a barra do comando
      texto: (m.text ?? m.caption ?? '').replace(/@\w+bot\b/gi, '').replace(/^\/\w+\s*/, '').trim(),
      audio: audio ? { fileId: audio.file_id, mime: audio.mime_type ?? 'audio/ogg', duracao: audio.duration ?? 0 } : undefined,
      nome: m.from?.first_name ?? '',
    };
  })
  .filter((m) => m.texto || m.audio) // figurinha, foto sem legenda etc. ficam de fora
  .map((m) => ({ json: m }));

// Nó Code "Transcrever áudios" do workflow "Bot da Pauta" (modo: Run Once for All Items)
// Para cada mensagem de voz: baixa o arquivo no Telegram (getFile devolve o caminho, depois baixa o .ogg)
// e pede ao Gemini a transcrição. O texto transcrito vira a pergunta do AI Agent, que continua só com texto.
// Mensagem de texto passa direto. Os erros saem sem o token do bot e sem a chave do Gemini.

const token = $env.TELEGRAM_BOT_TOKEN;
const chave = $env.GEMINI_API_KEY;
const semSegredos = (e) => String(e?.message ?? e).split(token).join('***').split(chave).join('***');
const esperar = (ms) => new Promise((r) => setTimeout(r, ms));
const DURACAO_MAXIMA = 180; // segundos

const transcrever = async (audio) => {
  const arquivo = await this.helpers.httpRequest({
    url: `https://api.telegram.org/bot${token}/getFile`,
    qs: { file_id: audio.fileId },
    json: true,
  });
  const bruto = await this.helpers.httpRequest({
    url: `https://api.telegram.org/file/bot${token}/${arquivo.result.file_path}`,
    encoding: 'arraybuffer',
  });
  const buffer = Buffer.isBuffer(bruto) ? bruto : bruto?.type === 'Buffer' ? Buffer.from(bruto.data) : Buffer.from(bruto);

  const pedido = {
    method: 'POST',
    url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-lite-latest:generateContent',
    headers: { 'x-goog-api-key': chave },
    json: true,
    timeout: 30000,
    body: {
      contents: [{
        role: 'user',
        parts: [
          { text: 'Transcreva este áudio em português do Brasil, exatamente o que foi dito, sem comentários nem aspas. Se não houver fala, responda apenas: (sem fala)' },
          { inline_data: { mime_type: audio.mime, data: buffer.toString('base64') } },
        ],
      }],
      generationConfig: { temperature: 0 },
    },
  };

  // O Gemini grátis às vezes devolve 503 (alta demanda): mais uma tentativa depois de 3 s
  let resposta;
  try {
    resposta = await this.helpers.httpRequest(pedido);
  } catch (e) {
    await esperar(3000);
    resposta = await this.helpers.httpRequest(pedido);
  }
  const texto = (resposta.candidates?.[0]?.content?.parts ?? []).map((p) => p.text ?? '').join('').trim();
  if (!texto || texto === '(sem fala)') throw new Error('o áudio veio sem fala reconhecível');
  return texto;
};

const saida = [];
for (const [i, item] of $input.all().entries()) {
  const m = item.json;
  if (!m.audio) {
    saida.push({ json: { ...m, transcricao: '' }, pairedItem: i });
    continue;
  }
  if (m.audio.duracao > DURACAO_MAXIMA) {
    saida.push({ json: { ...m, transcricao: '', texto: `Mandei um áudio de ${m.audio.duracao} s, acima do limite de ${DURACAO_MAXIMA} s. Avise que só entende áudio de até 3 minutos.` }, pairedItem: i });
    continue;
  }
  try {
    const transcricao = await transcrever(m.audio);
    // Se o áudio veio com legenda, a legenda vai junto
    saida.push({ json: { ...m, transcricao, texto: [m.texto, transcricao].filter(Boolean).join('\n') }, pairedItem: i });
  } catch (e) {
    saida.push({
      json: { ...m, transcricao: '', texto: 'Mandei um áudio, mas ele não pôde ser transcrito. Peça para eu escrever a pergunta.', erroAudio: semSegredos(e) },
      pairedItem: i,
    });
  }
}
return saida;
